-- CAB-0002: scoped editorial import. Apply after the portrait assets are deployed.

begin;

do $$ begin
 if (select count(*) from public.entities where slug in ('dap','pbb') and type='party') <> 2 then raise exception 'CAB-0002: missing party parent'; end if;
 if exists(select 1 from public.entities where slug in ('fadillah-yusof','anthony-loke') and (type <> 'politician' or owner_id is not null)) then raise exception 'CAB-0002: profile type or ownership conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('petra jaya','seremban') and slug not in ('fadillah-yusof','anthony-loke')) then raise exception 'CAB-0002: constituency identity collision requires review'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'CAB-0002:%' and (m.source_type <> 'editorial' or e.slug not in ('fadillah-yusof','anthony-loke') or m.import_key not like 'CAB-0002:' || e.slug || ':%')) then raise exception 'CAB-0002: milestone identity conflict'; end if;
end $$;

insert into public.entities (type, parent_id, slug, name, bloc, position, constituency, state, description, website, photo_path, photo_source_url, photo_credit, profile_checked_at, profile_sources)
select 'politician', parent.id, 'fadillah-yusof', 'Fadillah Yusof', 'government', 'Deputy Prime Minister; Minister of Energy Transition and Water Transformation', 'Petra Jaya', 'Sarawak', 'Fadillah Yusof is Deputy Prime Minister and Minister of Energy Transition and Water Transformation. He represents Petra Jaya in Sarawak. He is a member of Parti Pesaka Bumiputera Bersatu (PBB), part of Gabungan Parti Sarawak (GPS).', 'https://www.petra.gov.my/', '/portraits/fadillah-yusof.webp', 'https://www.parlimen.gov.my/images/webuser/ahli/2022/P194.jpg', 'Parliament of Malaysia', '2026-11-08', '[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Petra Jaya", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4233"}, {"label": "PBB council meeting · 4 Nov 2026", "url": "https://lifenewsagency.com/fadillah-pbb-supreme-council-sarawak-election-preparations/"}]'::jsonb from public.entities parent where parent.slug='pbb'
on conflict (slug) do update set parent_id=excluded.parent_id, name=excluded.name, bloc=excluded.bloc, position=excluded.position, constituency=excluded.constituency, state=excluded.state, description=excluded.description, website=excluded.website, photo_path=excluded.photo_path, photo_source_url=excluded.photo_source_url, photo_credit=excluded.photo_credit, profile_checked_at=excluded.profile_checked_at, profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null;

insert into public.entities (type, parent_id, slug, name, bloc, position, constituency, state, description, website, photo_path, photo_source_url, photo_credit, profile_checked_at, profile_sources)
select 'politician', parent.id, 'anthony-loke', 'Anthony Loke Siew Fook', 'government', 'Minister of Transport; Secretary-General of DAP', 'Seremban', 'Negeri Sembilan', 'Anthony Loke Siew Fook is Minister of Transport and Member of Parliament for Seremban, Negeri Sembilan. He is Secretary-General of the Democratic Action Party (DAP), a component of Pakatan Harapan.', 'https://www.mot.gov.my/', '/portraits/anthony-loke.webp', 'https://www.parlimen.gov.my/images/webuser/ahli/2022/P128.png', 'Parliament of Malaysia', '2026-11-08', '[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Seremban", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4167"}, {"label": "DAP · current leadership", "url": "https://dapmalaysia.org/en/our-leaders/"}]'::jsonb from public.entities parent where parent.slug='dap'
on conflict (slug) do update set parent_id=excluded.parent_id, name=excluded.name, bloc=excluded.bloc, position=excluded.position, constituency=excluded.constituency, state=excluded.state, description=excluded.description, website=excluded.website, photo_path=excluded.photo_path, photo_source_url=excluded.photo_source_url, photo_credit=excluded.photo_credit, profile_checked_at=excluded.profile_checked_at, profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null;

do $$ begin if (select count(*) from public.entities where slug in ('fadillah-yusof','anthony-loke') and type='politician' and owner_id is null) <> 2 then raise exception 'CAB-0002: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id, import_key, title, category, status, progress, target_date, promise_date, promise_url, evidence_date, evidence_url, description, progress_note, progress_checked_at, source_type, is_sample)
select e.id, 'CAB-0002:fadillah-yusof:re-capacity-35-2030', 'Reach 35% installed renewable-energy capacity by 2030', 'Environment', 'in_progress', null, '2030-12-31', '2026-04-21', 'https://www.bernama.com/en/news.php/?id=2547401', '2026-04-21', 'https://www.bernama.com/en/news.php/?id=2547401', 'Fadillah stated that installed renewable-energy capacity should rise to 35% by 2030 or earlier under the national energy transition programme.', 'His April 2026 statement reported 31% installed renewable capacity as of December 2025 and continuing solar and storage programmes. That is a capacity-share metric, not promise-completion progress. Completion is left blank; the target is not recorded as achieved.', '2026-11-08', 'editorial', false from public.entities e where e.slug='fadillah-yusof'
on conflict (import_key) do update set title=excluded.title, category=excluded.category, status=excluded.status, progress=excluded.progress, target_date=excluded.target_date, promise_date=excluded.promise_date, promise_url=excluded.promise_url, evidence_date=excluded.evidence_date, evidence_url=excluded.evidence_url, description=excluded.description, progress_note=excluded.progress_note, progress_checked_at=excluded.progress_checked_at, source_type=excluded.source_type, is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial';

insert into public.milestones (entity_id, import_key, title, category, status, progress, target_date, promise_date, promise_url, evidence_date, evidence_url, description, progress_note, progress_checked_at, source_type, is_sample)
select e.id, 'CAB-0002:fadillah-yusof:nrw-28-8-2030', 'Reduce national non-revenue water to 28.8% by 2030', 'Infrastructure', 'in_progress', null, '2030-12-31', '2026-02-24', 'https://bernama.com/bm/news.php?id=2526991', '2026-02-24', 'https://bernama.com/bm/news.php?id=2526991', 'In Parliament, Fadillah stated a 28.8% national non-revenue-water target for 2030 while explaining the shortcomings of earlier targets.', 'The minister reported ongoing pipe-replacement and national NRW programmes. This record uses his stated 28.8% target, rather than the older 25% figure mentioned in the question. A dated, comparable national outcome against the revised target was not established in this batch, so no completion percentage is assigned.', '2026-11-08', 'editorial', false from public.entities e where e.slug='fadillah-yusof'
on conflict (import_key) do update set title=excluded.title, category=excluded.category, status=excluded.status, progress=excluded.progress, target_date=excluded.target_date, promise_date=excluded.promise_date, promise_url=excluded.promise_url, evidence_date=excluded.evidence_date, evidence_url=excluded.evidence_url, description=excluded.description, progress_note=excluded.progress_note, progress_checked_at=excluded.progress_checked_at, source_type=excluded.source_type, is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial';

insert into public.milestones (entity_id, import_key, title, category, status, progress, target_date, promise_date, promise_url, evidence_date, evidence_url, description, progress_note, progress_checked_at, source_type, is_sample)
select e.id, 'CAB-0002:anthony-loke:digital-my50-launch', 'Enable digital My50 pass purchase and renewal from July 2025', 'Digital', 'achieved', null, '2025-07-01', '2025-06-26', 'https://www.mot.gov.my/my/Ucapan%20YBM/Tahun%202025/My50%20Digitalisation%20talking%20points%5B1%5D.pdf', '2026-01-07', 'https://www.mot.gov.my/my/Kenyataan%20Media/Tahun%202025/SIARAN%20MEDIA%20-%20PRASARANA%20CATAT%20JUMLAH%20PENUMPANG%20TERTINGGI%20DALAM%20SEJARAH%20PADA%20TAHUN%202025.pdf', 'Loke announced that eligible My50 users could use TNG eWallet for digital pass purchase and renewal from 1 July 2025.', 'Prasarana’s January 2026 report confirms the 1 July 2025 launch and reports 556,618 digital passes purchased cumulatively in July–December 2025. Achieved refers to the service launch, not universal adoption, accessibility or the elimination of queues. No completion percentage is invented.', '2026-11-08', 'editorial', false from public.entities e where e.slug='anthony-loke'
on conflict (import_key) do update set title=excluded.title, category=excluded.category, status=excluded.status, progress=excluded.progress, target_date=excluded.target_date, promise_date=excluded.promise_date, promise_url=excluded.promise_url, evidence_date=excluded.evidence_date, evidence_url=excluded.evidence_url, description=excluded.description, progress_note=excluded.progress_note, progress_checked_at=excluded.progress_checked_at, source_type=excluded.source_type, is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial';

insert into public.milestones (entity_id, import_key, title, category, status, progress, target_date, promise_date, promise_url, evidence_date, evidence_url, description, progress_note, progress_checked_at, source_type, is_sample)
select e.id, 'CAB-0002:anthony-loke:road-fatalities-2030', 'Reduce road-traffic fatalities by 50% by 2030', 'Security', 'in_progress', null, '2030-12-31', '2026-10-21', 'https://hansard.parlimen.gov.my/hansard/dewan-rakyat/2026-10-21', '2026-10-21', 'https://hansard.parlimen.gov.my/hansard/dewan-rakyat/2026-10-21', 'Loke reaffirmed the 50% reduction target under Malaysia’s Road Safety Plan 2022–2030 during a parliamentary answer.', 'The parliamentary transcript records ongoing enforcement measures and development of the plan’s second phase, including motorcycle-safety interventions. It is marked draft by Parliament. A comparable fatality baseline and current outcome series were not established here, so the completion percentage remains blank. Delivery involves multiple agencies.', '2026-11-08', 'editorial', false from public.entities e where e.slug='anthony-loke'
on conflict (import_key) do update set title=excluded.title, category=excluded.category, status=excluded.status, progress=excluded.progress, target_date=excluded.target_date, promise_date=excluded.promise_date, promise_url=excluded.promise_url, evidence_date=excluded.evidence_date, evidence_url=excluded.evidence_url, description=excluded.description, progress_note=excluded.progress_note, progress_checked_at=excluded.progress_checked_at, source_type=excluded.source_type, is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial';

commit;
